package com.mo.economy_system.target.neoforge1211.client;
import com.mo.economy_system.common.network.*;import com.mo.economy_system.common.transfer.*;import net.minecraft.client.Minecraft;
public final class NeoForge1211CheckedFileTransferClient{private NeoForge1211CheckedFileTransferClient(){}public static void handle(CheckedFileTransferRequestMessage m){Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.getConnection()==null||!mc.player.getUUID().equals(m.targetPlayerId()))return;var entry=NeoForge1211ClientFileCheckClientRuntime.manifest().find(new CheckedFileTransferManifestCache.Key(m.requesterPlayerId(),m.checkType(),m.fileName()),System.nanoTime());if(entry.isEmpty()){com.mo.economy_system.network.EconomySystem_NetworkManager.sendToServer(CheckedFileTransferOutgoing.control(m,CheckedFileTransferControl.error(CheckedFileTransferControlStatus.FAILED,"STALE_CHECK")));return;}mc.setScreen(new Screen_CheckedFileTransferConsent(m,entry.get(),mc.getConnection()));}public static void control(CheckedFileTransferControlResponseMessage m){CheckedFileTransferIncomingRuntime.control(m);}public static void chunk(CheckedFileTransferChunkResponseMessage m){CheckedFileTransferIncomingRuntime.chunk(m);}}
